func (workflowWhere[Q]) AliasedAs(alias string) workflowWhere[Q] {
	return buildWorkflowWhere[Q](buildWorkflowColumns(alias))
}

func buildWorkflowWhere[Q psql.Filterable](cols workflowColumns) workflowWhere[Q] {
	return workflowWhere[Q]{
		cols:              cols,
		ID:                psql.Where[Q, string](cols.ID.Expression),
		CreatedAt:         psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		UpdatedAt:         psql.Where[Q, time.Time](cols.UpdatedAt.Expression),
		WorkspaceID:       psql.Where[Q, string](cols.WorkspaceID.Expression),
		Key:               psql.Where[Q, string](cols.Key.Expression),
		Name:              psql.Where[Q, string](cols.Name.Expression),
		Description:       psql.Where[Q, string](cols.Description.Expression),
		AutomaticEnabled:  psql.Where[Q, bool](cols.AutomaticEnabled.Expression),
		ManualEnabled:     psql.Where[Q, bool](cols.ManualEnabled.Expression),
		AutomaticProvider: psql.Where[Q, bool](cols.AutomaticProvider.Expression),
		State:             psql.Where[Q, string](cols.State.Expression),
		BuiltinKey:        psql.WhereNull[Q, string](cols.BuiltinKey.Expression),
		CollectionID:      psql.WhereNull[Q, string](cols.CollectionID.Expression),
		Parameters:        psql.Where[Q, types.JSON[model.JSONMap]](cols.Parameters.Expression),
		CurrentVersion:    psql.Where[Q, int64](cols.CurrentVersion.Expression),
		CreatedBy:         psql.Where[Q, string](cols.CreatedBy.Expression),
		UpdatedBy:         psql.Where[Q, string](cols.UpdatedBy.Expression),
		DeletedAt:         psql.WhereNull[Q, time.Time](cols.DeletedAt.Expression),
		Version:           psql.Where[Q, int64](cols.Version.Expression),
		Role:              psql.WhereNull[Q, string](cols.Role.Expression),
		R:                 workflowWhereR[Q]{cols: cols},
	}
}

